                if (d2 && typeof d2 === "object") { for (var dk in d2) { if (dk !== "__eqilRng" && Object.prototype.hasOwnProperty.call(d2, dk)) { any = true; break; } } }
                if (any) { d2.__eqilRng = a; }
            } catch (e) {}
        }
    }

    /* 10. A complete run has no live submit button. */
    var SUBMIT_IDS = ["nextPeriodBtn", "submitDecisionBtn", "submitBtn", "submitPeriodBtn", "sendDecisionBtn", "roundSubmitBtn", "enviarBtn", "decisionBtn"];
    function closeRun() {
        var f = sim(), done = false, i, b;
        if (!f || !f.state) { return; }
        try { done = typeof f.isRunComplete === "function" ? !!f.isRunComplete() : !!(f._finished || Number(f.state.currentPeriod) > Number(f.state.maxPeriods)); } catch (e) { return; }
        for (i = 0; i < SUBMIT_IDS.length; i++) {
            b = document.getElementById(SUBMIT_IDS[i]);
